// Troca `\` por `/`, junta barras repetidas e tira os segmentos `..`.
const normalizePath = path => String(path).replace(/\\/g, '/').replace(/\/+/g, '/').split('/').filter((seg, i) => {
  if (seg === '.' || seg === '') return i === 0;
  if (seg === '..') return false;
  return true;
}).join('/');
/**
 * URL completa de um arquivo salvo em `assets/`. URLs http(s) passam direto;
 * qualquer outro esquema (`javascript:`, `data:`) vira null.
 *
 * Recebe o `app` porque o admin e o fórum têm cada um o seu.
 */
export const resolveAssetUrl = (assetPath, app) => {
  if (!assetPath) return null;
  if (/^https?:\/\//i.test(assetPath)) return assetPath;
  if (/^[a-z][a-z0-9+.-]*:/i.test(assetPath)) return null;
  const normalized = normalizePath(assetPath);
  const base = app.forum.attribute('assetsBaseUrl') || "".concat(app.forum.attribute('baseUrl'), "/assets");
  return "".concat(base.replace(/\/+$/, ''), "/").concat(normalized);
};
export const safeCssUrl = url => {
  const escaped = String(url).replace(/"/g, '\\"');
  return "url(\"".concat(escaped, "\")");
};
flarum.reg.add('ramon-auth-modals', 'common/utils/assetUrl', { resolveAssetUrl: resolveAssetUrl,safeCssUrl: safeCssUrl, });